//! What the Tilo fleet's signed manifests say about each app, compiled in, so an app that is not on
//! this device yet is known as fully as one that is: where it runs, the names and words people know
//! it by, the documents it creates and the actions it offers while closed. Generated by
//! `tools/apps/generate_catalogue_fleet.py`.

/// An action an app offers while closed (`[[offers]]`), as `tilo-app surface` writes it from
/// what the app's code publishes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FleetAction {
    pub resource: &'static str,
    /// The kind of that resource; empty when it is the resource itself.
    pub resource_kind: &'static str,
    pub action: &'static str,
    pub label: &'static str,
    /// Empty when the manifest gives none.
    pub description: &'static str,
    /// What it may do: `read`, `undoable` or `outside`.
    pub kind: &'static str,
    /// How it acts: `document`, `effect` or `view`.
    pub operation: &'static str,
    /// A person confirms it first.
    pub confirm: bool,
    /// The parameter one typed line fills; empty when it asks for none.
    pub asks: &'static str,
    /// The other words people use for it, each ended by a unit separator ([`Self::keywords`]).
    keywords: &'static str,
    /// Its picture, by its Lucide name; empty when it has none.
    pub icon: &'static str,
}

impl FleetAction {
    /// The other words people use for it.
    pub fn keywords(&self) -> impl Iterator<Item = &'static str> {
        self.keywords
            .split('\u{1f}')
            .filter(|word| !word.is_empty())
    }

    /// One line of an app's [`FleetApp::offers`]: its fields in order, each after a tab.
    fn read(line: &'static str) -> Option<Self> {
        let mut fields = line.split('\t');
        let mut next = || fields.next();
        Some(Self {
            resource: next()?,
            resource_kind: next()?,
            action: next()?,
            label: next()?,
            description: next()?,
            kind: next()?,
            operation: next()?,
            confirm: next()? == "1",
            asks: next()?,
            keywords: next()?,
            icon: next()?,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FleetApp {
    pub id: &'static str,
    pub name: &'static str,
    /// Its manifest's category ("Office"); empty when it has none.
    pub category: &'static str,
    /// The platforms it declares (`linux`, `macos`, `web`, `tilo-os`).
    pub platforms: &'static [&'static str],
    /// The registry's tag line; empty when it has none.
    pub tagline: &'static str,
    /// Its name in other languages (`[package.names]`).
    pub names: &'static [&'static str],
    /// Every language's `search-keywords`.
    pub keywords: &'static [&'static str],
    /// `(kind, label)` of each document it creates.
    pub resource_types: &'static [(&'static str, &'static str)],
    /// The actions it offers while closed, one line each ([`Self::actions`]): one string, so
    /// the hundreds the fleet offers cost the program what their text does.
    offers: &'static str,
}

impl FleetApp {
    /// The actions it offers while closed (`[[offers]]`).
    pub fn actions(&self) -> impl Iterator<Item = FleetAction> {
        self.offers.lines().filter_map(FleetAction::read)
    }
}

mod generated;

#[must_use]
pub fn apps() -> &'static [FleetApp] {
    generated::APPS
}

/// The fleet's metadata for `package_id`. A development build publishes the same apps under
/// `dev.tilo.`, which resolve to their `so.tilo.` entry.
#[must_use]
pub fn metadata(package_id: &str) -> Option<&'static FleetApp> {
    let wanted = canonical(package_id);
    apps().iter().find(|app| app.id == wanted)
}

/// The signed `surface.toml` of `package_id`, as its package ships it: the declarations a
/// program in a workspace compiles that app against there.
#[cfg(feature = "surfaces")]
#[must_use]
pub fn surface(package_id: &str) -> Option<&'static str> {
    let wanted = canonical(package_id);
    generated::SURFACES
        .iter()
        .find(|(app, _)| *app == wanted)
        .map(|(_, surface)| *surface)
}

/// Every package that ships a surface, by its id, with the name people call it: the apps of
/// [`apps`] and the services whose resources and actions the workspace holds all the same (the
/// on-screen keyboard's, the launcher's). What `tilo sdk gen` writes types for and the API's
/// description describes, so neither leaves out an action a program may invoke.
#[cfg(feature = "surfaces")]
pub fn surfaced() -> impl Iterator<Item = (&'static str, &'static str, &'static str)> {
    generated::SURFACES.iter().map(|(id, surface)| {
        let name = generated::SURFACE_NAMES
            .iter()
            .find(|(named, _)| named == id)
            .map_or(*id, |(_, name)| *name);
        (*id, name, *surface)
    })
}

/// Whose a record of `kind` kept by `package_id` is, as the app's manifest declares it
/// (`[resources] own`): each member's own, or the workspace's. Read from a table apart from
/// [`apps`], so a host that asks only this links none of the rest.
#[must_use]
pub fn scope(package_id: &str, kind: &str) -> Scope {
    let app = canonical(package_id);
    if generated::OWN_KINDS
        .iter()
        .any(|(own_app, own_kind)| *own_app == app && *own_kind == kind)
    {
        Scope::Member
    } else {
        Scope::Workspace
    }
}

/// The kinds `package_id`'s manifest declares each member keeps as their own
/// (`[resources] own`).
pub fn own_kinds(package_id: &str) -> impl Iterator<Item = &'static str> {
    let app = canonical(package_id).into_owned();
    generated::OWN_KINDS
        .iter()
        .filter(move |(own_app, _)| *own_app == app)
        .map(|(_, kind)| *kind)
}

/// Whether a window of `package_id` is the person's own, as the app declares it
/// (`ResourceApp::WINDOWS_ARE_PERSONAL`): it shows what the person keeps for themselves, and
/// never stands on a workspace's shared desktop.
#[must_use]
pub fn windows_are_own(package_id: &str) -> bool {
    let app = canonical(package_id);
    generated::OWN_WINDOWS
        .iter()
        .any(|own| own.eq_ignore_ascii_case(&app))
}

/// Whether each window of `package_id` shows a document of its own (a workbook, a terminal's
/// session), as the app itself declares (`ResourceApp::WINDOW_RESOURCE`). Such an app keeps none
/// for the workspace: one of its documents is named by its own id.
#[must_use]
pub fn windows_hold_documents(package_id: &str) -> bool {
    let app = canonical(package_id);
    generated::DOCUMENT_WINDOWS
        .iter()
        .any(|held| held.eq_ignore_ascii_case(&app))
}

/// Whose a record of a kind is ([`scope`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Scope {
    /// The workspace's: every member reads it as their role allows.
    Workspace,
    /// One member's own: only their devices receive it, and only they read or change it,
    /// whatever their role.
    Member,
}

/// `package_id` as the fleet names it: a development build's `dev.tilo.` app is its `so.tilo.` one,
/// and an id an app was published under before names that app.
fn canonical(package_id: &str) -> std::borrow::Cow<'_, str> {
    let canonical = package_id
        .strip_prefix("dev.tilo.")
        .map_or_else(|| package_id.to_owned(), |name| format!("so.tilo.{name}"));
    let previous = generated::PREVIOUS
        .iter()
        .find(|(old, _)| old.eq_ignore_ascii_case(&canonical));
    previous.map_or(std::borrow::Cow::Owned(canonical), |(_, app)| {
        std::borrow::Cow::Borrowed(*app)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_fleet_knows_documents_and_closed_actions() {
        let sheets = metadata("so.tilo.sheets").expect("Sheets is in the fleet");
        assert!(
            sheets
                .resource_types
                .contains(&("sheets.workbook", "Workbook"))
        );
        assert!(!sheets.tagline.is_empty());
        assert!(sheets.keywords.contains(&"spreadsheet"));
        assert_eq!(
            metadata("dev.tilo.sheets").map(|app| app.id),
            Some("so.tilo.sheets")
        );
        assert_eq!(scope("so.tilo.mail", "mail.mailbox"), Scope::Workspace);
        assert_eq!(
            scope("dev.tilo.settings", "settings.root"),
            Scope::Workspace
        );
        assert_eq!(scope("so.tilo.mail", "tilo.rich-text"), Scope::Workspace);
        assert_eq!(scope("so.tilo.sheets", "sheets.workbook"), Scope::Workspace);
        // Settings shows what the person keeps for themselves, so its windows are theirs;
        // Mail's show the workspace's accounts, so they are the workspace's.
        assert!(windows_are_own("dev.tilo.settings"));
        assert!(!windows_are_own("so.tilo.mail"));
        assert_eq!(scope("so.tilo.mail", "mail.copies"), Scope::Workspace);
        assert!(!windows_are_own("so.tilo.chat"));
        assert!(windows_hold_documents("so.tilo.sheets"));
        assert!(windows_hold_documents("dev.tilo.terminal"));
        assert!(!windows_hold_documents("so.tilo.tasks"));
        assert!(!windows_hold_documents("so.tilo.notes"));
        let calendar = metadata("so.tilo.calendar").expect("Calendar is in the fleet");
        assert!(
            calendar
                .actions()
                .any(|action| action.action == "show-tasks")
        );
    }

    #[test]
    fn a_tilolang_app_is_known_as_fully_as_a_native_one() {
        let notes = metadata("so.tilo.lang.notes").expect("Notes is in the fleet");
        assert_eq!(notes.name, "Notes");
        assert_eq!(notes.category, "Office");
        assert!(notes.tagline.contains("together"));
        assert!(notes.keywords.contains(&"memo"));
        assert!(notes.names.contains(&"Notizen"));
        assert!(
            notes
                .resource_types
                .contains(&("tl.so.tilo.lang.notes.Notebook", "Notebook"))
        );
        assert_eq!(
            notes.actions().next().map(|action| action.action),
            Some("new_note")
        );
        assert!(windows_are_own("so.tilo.shell"));
        // An id the app was published under before names it.
        assert_eq!(
            metadata("so.tilo.lang.todo").map(|app| app.id),
            Some("so.tilo.lang.tasks")
        );
        // The tilolang package's surface is generated from the same metadata, so a program a
        // server compiles for a workspace with no app installed reads Notes' records there.
        let surface = surface("so.tilo.lang.notes").expect("Notes ships its surface");
        assert!(surface.contains("tl.so.tilo.lang.notes.Notebook"));
        assert!(surface.contains("tl.so.tilo.lang.notes.Note"));
        // It runs where its runtime bundle runs, which is a Linux binary: a person is never
        // offered it on a Mac or in a browser tab, where starting it can only fail.
        assert_eq!(notes.platforms, ["linux"]);
    }
}
